package com.focusflow.api.security; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.AuthorityUtils; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.*; @Component public class JwtFilter extends OncePerRequestFilter { private final JwtService jwt; public JwtFilter(JwtService j){jwt=j;} @Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException {String h=r.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer "))try{String id=jwt.userId(h.substring(7));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(id,null,AuthorityUtils.NO_AUTHORITIES));}catch(Exception ignored){} c.doFilter(r,s);} }
